# ============================================================
# CREAR MODELO
# ============================================================

def crear_modelo():

    """
    Reconstruye únicamente la arquitectura.

    En este punto todavía NO se cargaron
    los pesos entrenados.
    """

    modelo = (
        tf.keras.models.model_from_json(
            MODEL_JSON
        )
    )

    return modelo


# ============================================================
# CARGAR MODELO ENTRENADO
# ============================================================

def cargar_modelo(
    ruta_pesos=None
):

    """
    Crea la arquitectura y carga
    los pesos obtenidos durante el entrenamiento.

    Devuelve el modelo listo para usar.
    """

    modelo = crear_modelo()


    if ruta_pesos is None:

        ruta_pesos = (
            Path(__file__)
            .resolve()
            .parent
            / "plagas.weights.h5"
        )


    modelo.load_weights(
        ruta_pesos
    )


    return modelo


# ============================================================
# INSPECCIÓN MANUAL
# ============================================================

if __name__ == "__main__":

    modelo = cargar_modelo()

    print()
    print("=" * 70)
    print("MODELO: PLAGAS")
    print("=" * 70)

    print(
        "Entrada:",
        modelo.input_shape
    )

    print(
        "Salida:",
        modelo.output_shape
    )

    print(
        "Parámetros:",
        f"{modelo.count_params():,}"
    )

    print()

    modelo.summary()
